export interface PayrollLine {
  employeeId: string;
  netAmountCents: number;
  currency: string;
  bankAccountToken: string;
}

export interface PayrollRun {
  id: string;
  companyId: string;
  payDate: string;
  lines: PayrollLine[];
}

export type DisbursementStatus = "pending" | "submitted" | "failed";

export interface DisbursementRepo {
  status(runId: string, employeeId: string): Promise<DisbursementStatus | null>;
  markPending(runId: string, employeeId: string): Promise<void>;
  markSubmitted(runId: string, employeeId: string, transferId: string): Promise<void>;
  markFailed(runId: string, employeeId: string, reason: string): Promise<void>;
}

export class TransientBankError extends Error {}

import { TransientBankError } from "./types";

export interface TransferRequest {
  amountCents: number;
  currency: string;
  destinationToken: string;
  reference: string;
  idempotencyKey: string;
}

export class BankClient {
  constructor(private readonly baseUrl: string, private readonly apiKey: string) {}

  async createTransfer(req: TransferRequest): Promise<{ transferId: string }> {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 10_000);
    try {
      const res = await fetch(`${this.baseUrl}/v2/transfers`, {
        method: "POST",
        signal: controller.signal,
        headers: {
          Authorization: `Bearer ${this.apiKey}`,
          "Content-Type": "application/json",
          "Idempotency-Key": req.idempotencyKey,
        },
        body: JSON.stringify({
          amount: req.amountCents,
          currency: req.currency,
          destination: req.destinationToken,
          reference: req.reference,
        }),
      });
      if (res.status >= 500 || res.status === 429) {
        throw new TransientBankError(`bank returned ${res.status}`);
      }
      if (!res.ok) {
        throw new Error(`transfer rejected: ${res.status} ${await res.text()}`);
      }
      const data = (await res.json()) as { id: string };
      return { transferId: data.id };
    } catch (err) {
      if ((err as Error).name === "AbortError") {
        throw new TransientBankError("bank request timed out");
      }
      throw err;
    } finally {
      clearTimeout(timer);
    }
  }
}

import { BankClient } from "./bankClient";
import { DisbursementRepo, PayrollLine, PayrollRun, TransientBankError } from "./types";

const MAX_ATTEMPTS = 4;

function delay(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export class PayrollDisburser {
  constructor(private readonly bank: BankClient, private readonly repo: DisbursementRepo) {}

  async disburse(run: PayrollRun): Promise<{ submitted: number; failed: number }> {
    let submitted = 0;
    let failed = 0;
    for (const line of run.lines) {
      const current = await this.repo.status(run.id, line.employeeId);
      if (current === "submitted") {
        submitted++;
        continue;
      }
      await this.repo.markPending(run.id, line.employeeId);
      try {
        const transferId = await this.payWithRetry(run, line);
        await this.repo.markSubmitted(run.id, line.employeeId, transferId);
        submitted++;
      } catch (err) {
        await this.repo.markFailed(run.id, line.employeeId, (err as Error).message);
        failed++;
      }
    }
    return { submitted, failed };
  }

  private async payWithRetry(run: PayrollRun, line: PayrollLine): Promise<string> {
    for (let attempt = 1; ; attempt++) {
      const idempotencyKey = `payroll:${run.id}:${line.employeeId}:${attempt}`;
      try {
        const { transferId } = await this.bank.createTransfer({
          amountCents: line.netAmountCents,
          currency: line.currency,
          destinationToken: line.bankAccountToken,
          reference: `Salary ${run.payDate}`,
          idempotencyKey,
        });
        return transferId;
      } catch (err) {
        if (!(err instanceof TransientBankError) || attempt >= MAX_ATTEMPTS) {
          throw err;
        }
        await delay(250 * 2 ** attempt);
      }
    }
  }
}
